// ─── Flatten Medusa Variants → ERPNext Items ─────────────────────
// ERPNext expects flat "Items" while Medusa has nested Product→Variants.
// For each variant, we create a separate ERPNext Item.
//
// Gotcha #1 (SKU Discipline): Every variant MUST have a unique SKU.
// Gotcha #2 (Variant Mismatch): We sync as flat items, not ERPNext templates.

const event = $input.first().json;
const product = event.data || {};
const variants = product.variants || [];
const metadata = product.metadata || {};

const items = [];

for (const variant of variants) {
  // Determine the SKU (item_code for ERPNext)
  const sku = variant.sku 
    || `INVT-${metadata.inventory_item_id || product.id?.replace('prod_', '')}-${variant.title?.replace(/\s+/g, '-').toUpperCase() || 'DEFAULT'}`;

  // Determine the item name
  const itemName = variants.length === 1 && variant.title === 'Default'
    ? product.title
    : `${product.title} (${variant.title})`;

  // Get price (Medusa stores in cents)
  const priceEntry = (variant.prices || [])[0] || {};
  const priceInCents = priceEntry.amount || 0;
  const priceDollars = priceInCents / 100;

  items.push({
    json: {
      // ERPNext Item fields
      item_code: sku,
      item_name: itemName,
      item_group: 'Products',
      stock_uom: 'Nos',
      description: product.description || itemName,
      standard_rate: priceDollars,
      valuation_rate: priceDollars,
      is_stock_item: 1,
      has_variants: 0,
      // Medusa linking metadata
      custom_medusa_product_id: product.id,
      custom_medusa_variant_id: variant.id,
      custom_medusa_handle: product.handle,
      // Image (first product image)
      image: (product.images || [])[0]?.url || null,
      // Context
      event_type: event.event,
      is_update: event.event === 'product.updated',
    }
  });
}

if (items.length === 0) {
  // Fallback: create a single item from the product
  items.push({
    json: {
      item_code: `INVT-${metadata.inventory_item_id || product.id?.replace('prod_', '')}`,
      item_name: product.title || 'Unknown Item',
      item_group: 'Products',
      stock_uom: 'Nos',
      description: product.description || '',
      standard_rate: 0,
      valuation_rate: 0,
      is_stock_item: 1,
      has_variants: 0,
      custom_medusa_product_id: product.id,
      event_type: event.event,
      is_update: event.event === 'product.updated',
    }
  });
}

console.log(`[ERPNext Sync] Flattened ${variants.length} variant(s) → ${items.length} ERPNext Item(s)`);
return items;

// ─── Log sync result ──────────────────────────────────────────────
const item = $input.first().json;
console.log(`[ERPNext Sync] ✓ Item synced: ${item.data?.name || item.item_code || 'unknown'}`);
return [$input.first()];
